import countriesJson from '../data/countries.json'
import type { CountryShape } from './countries'

// Facts about one country, generated by scripts/make-country-data.mjs.
export type CountryFacts = {
  // ISO 3166-1 alpha-3 code, e.g. "PER". Links facts to the globe outlines.
  isoAlpha3: string
  commonName: string
  officialName: string
  // Most countries have one capital; a few have several (e.g. South Africa).
  capitals: string[]
  // Total area including inland water, in square kilometres.
  areaKm2: number
  population: number
  populationYear: number
  // Human Development Index (0–1), before adjusting for inequality. Null when
  // UNDP has no value for the country. Not yet shown anywhere in the app.
  hdi: number | null
  hdiYear: number | null
  // Inequality-adjusted Human Development Index (0–1). Null when UNDP has no
  // value for the country, shown as "no data".
  ihdi: number | null
  ihdiYear: number | null
  // Our own estimate of the IHDI, worked out from the HDI, for countries that
  // have an HDI but no IHDI (null otherwise). Always shown as "estimated".
  ihdiEstimate: number | null
}

// All 195 countries (193 UN members + Vatican City and Palestine), keyed by
// ISO alpha-3 code.
export const countryFacts: Record<string, CountryFacts> = countriesJson

// The name to show for a country outline on the globe: our common name for the
// 195 countries, otherwise the map data's name (e.g. Greenland, Kosovo).
export function countryDisplayName(shape: CountryShape): string {
  const facts = shape.isoAlpha3 === null ? undefined : countryFacts[shape.isoAlpha3]
  return facts?.commonName ?? shape.name
}
